theme.css:
/* Stellar by HTML5 UP | html5up.net | @ajlkn | CC BY 3.0.
 * Adapted for ImmichPager; composition, typography and accessibility modified. */
:scope { background:#f1edf5; padding-block:32px; }
.ip-hero { max-width:1120px; width:calc(100% - 64px); padding:0; }
.ip-hero .ip-header { color:#43384f; --pager-muted:#655a70; padding:24px 32px 32px; }
.ip-title { font-size:clamp(var(--pager-title-min-size), calc(1.5rem + 2vw), var(--pager-title-size)); font-weight:var(--pager-title-font-weight); letter-spacing:-.025em; line-height:1.15; }
.ip-description { max-width:38em; line-height:1.7; }
.ip-hero .ip-banner { order:0; width:100%; height:var(--pager-banner-height); border-radius:8px 8px 0 0; margin:0; }
.ip-hero .ip-navigation { order:1; background:#ffffff; color:#43384f; border:0; padding:20px 24px; margin:0; }
.page-blocks { max-width:1120px; width:calc(100% - 64px); margin:auto; background:#ffffff; border-radius:0 0 8px 8px; }
.ip-block::before { display:none; }
.ip-block { padding-block:36px; }
.ip-block .block-heading { font-weight:400; }
.ip-block .block-heading::after { content:''; display:block; width:64px; height:2px; margin-top:16px; background:#cbb9d7; }
.ip-footer { color:#655a70; }
@media(max-width:760px) { :scope { padding-block:16px; } .ip-hero, .page-blocks { width:calc(100% - 32px); } .ip-hero .ip-header { padding:16px 16px 28px; } .ip-hero .ip-banner { height:280px; } .ip-hero .ip-navigation { padding:16px; } }

.ip-description { opacity:1; }
.ip-albums:not(.tiles) .ip-album-info p { opacity:1; color:var(--pager-muted); }
.ip-albums.tiles .ip-album-info p { opacity:1; color:#ffffff; }
